'use strict';
const lessons=JSON.parse(document.getElementById('lessons').textContent),main=document.getElementById('courseMain');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sourceLabels={workflow:'工作流是什么',nodes:'节点与模式',properties:'参数与类型',links:'端口与连接',t2i:'经典文生图',sample:'KSampler 参数',i2i:'图生图原理',lora:'LoRA 用法',error:'模型问题排查',h3:'导演台作者说明'};
const nodeNames={3:'视频 VAE',4:'音频 VAE',19:'RIFE 补帧',22:'音频分线点',23:'图像分线点',26:'帧率 ×2',30:'基础视频输出',38:'FL2VA 底模',39:'提示词编码器',78:'独立图片',90:'Prompt Rewriter LoRA',104:'4 步 LoRA',111:'LoRA 控制器',145:'导演台'};
const key='comfy-beginner-course-v1';let state={done:[],answers:{},cap:[],last:1},storage=true,current=0;
try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&typeof raw==='object'){state.done=Array.isArray(raw.done)?raw.done.filter(x=>Number.isInteger(x)&&x>=1&&x<=12):[];state.answers=raw.answers&&typeof raw.answers==='object'?raw.answers:{};state.cap=Array.isArray(raw.cap)?raw.cap:[];state.last=Number(raw.last)||1}}catch{storage=false}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{storage=false}updateProgress()}
function toast(text){const t=document.getElementById('courseToast');t.textContent=text;t.style.display='block';setTimeout(()=>t.style.display='none',2100)}
function updateProgress(){const done=new Set(state.done);document.getElementById('progressText').textContent=`${done.size} / 12`;document.getElementById('progressBar').style.width=(done.size/12*100)+'%';document.getElementById('storageNote').textContent=storage?'进度只保存在当前浏览器':'当前无法保存进度，本次仍可继续学习';document.getElementById('lessonNav').innerHTML=lessons.map(l=>`<button class="lesson-link ${current===l.id?'active':''}" onclick="openLesson(${l.id})" ${current===l.id?'aria-current="step"':''}><span class="lesson-num">${done.has(l.id)?'✓':String(l.id).padStart(2,'0')}</span><span>${esc(l.title)}<small>${esc(l.short)}</small></span></button>`).join('')}
function route(hash){history.replaceState(null,'',hash)}
function focusMain(){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function overview(){current=0;route('#overview');updateProgress();const next=lessons.find(l=>!state.done.includes(l.id))?.id||1;main.innerHTML=`${state.done.length===12?'<div class="complete-panel"><h2>12 课已完成，随时回来复习。</h2><p>下一步可以结合工作流图解，独立说出每条线的来源和去向。</p></div>':''}<section class="hero"><div class="eyebrow">COMFYUI / 从零开始的读图课</div><div class="hero-row"><div><h1>看懂一个节点，<br><span>再看懂一张图。</span></h1><p>不用先背英文缩写。跟着 12 节小课，从方块和连线讲起，逐步读懂你的 MiniMax H3 视频工作流。</p><div class="hero-actions"><button class="primary" onclick="openLesson(${next})">${state.done.length?'继续学习':'从第一课开始'} →</button><button onclick="openGlossary()">遇到生词，随时查</button></div></div><div class="hero-graphic" aria-label="学习路径：模型与要求送到生成过程，再输出图片与视频"><div class="eyebrow">从“这是什么”，到“我看懂了”</div><div><div class="mini-node">模型<small>准备工具</small></div><span class="arrow">↘</span><div class="mini-node highlight">生成<small>按条件处理</small></div></div><div><div class="mini-node">画面要求<small>文字 / 图片</small></div><span class="arrow">↗</span><div class="mini-node">输出<small>图片 / 视频</small></div></div><p style="font-size:11px;color:#a9bf9e;margin-bottom:0">每一步：需要什么 → 做什么 → 交出什么</p></div></div></section><div class="section-heading"><h2>一条循序渐进的学习路线</h2><span>每课：解释 + 图解 + 自测 + 真实节点</span></div><div class="route-strip"><div><b>01—04 先学会读图</b>从工作台、节点与端口，到最小文生图流程。</div><div><b>05—08 认识生成工具</b>分清模型、VAE、提示词、参数与 LoRA。</div><div><b>09—12 读懂你的工作流</b>理解视频，追踪 H3 连线，排查错误，完成练习。</div></div><div class="section-heading"><h2>12 节入门课</h2><span>可以随时跳转或回看</span></div><div class="lesson-cards">${lessons.map(l=>`<button class="lesson-card" onclick="openLesson(${l.id})"><span class="label">LESSON ${String(l.id).padStart(2,'0')}</span><h3>${esc(l.title)}</h3><p>${esc(l.short)}</p><span class="status">${state.done.includes(l.id)?'✓ 已读，可复习':'进入学习 →'}</span></button>`).join('')}</div><div class="gentle-note">这里的交互练习只用于理解原理，不生成图片、不提交视频任务，也不会产生 AI 运行费用。原始工作流保持只读。</div><footer>课程依据 ComfyUI 官方文档与本工作流快照编写；每课底部可查原文。学习记录只在当前浏览器保存，更换浏览器或清除网站数据后不会同步。</footer>`;focusMain()}
function openLesson(id){const l=lessons[id-1];if(!l)return;current=id;state.last=id;save();route('#lesson-'+id);main.innerHTML=`<header class="course-head"><div class="crumb">零基础学堂 / 第 ${id} 课，共 12 课</div><div class="eyebrow">${esc(l.short)}</div><h1>${esc(l.title)}</h1><div class="goal"><b>学完你能：</b>${esc(l.goal)}</div></header><article class="lesson-paper">${l.body}<div class="source-end">查证与延伸阅读：${l.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${sourceLabels[s.label]} ↗</a>`).join('')}<div style="margin-top:6px">通用原理与具体模型的配置分开理解；文档及界面可能随版本变化。</div></div></article><section class="lab" id="lab">${lab(l.visual)}</section><section class="knowledge-check"><div class="eyebrow">一个小问题 / 不计分</div><h3>${esc(l.q)}</h3><div class="quiz-options">${l.options.map((o,i)=>`<button id="option-${i}" onclick="answer(${i})">${String.fromCharCode(65+i)}　${esc(o)}</button>`).join('')}</div><p class="feedback" id="quizFeedback" aria-live="polite"></p></section><section class="node-links"><h3>回到你的真实工作流</h3>${l.nodes.map(n=>`<a href="index.html?node=${n}">#${n} ${esc(nodeNames[n]||'查看节点')} ↗</a>`).join('')}<p>打开的是讲解副本。可点击查看端口、参数和连线，不会执行原工作流。</p></section><div class="lesson-bottom"><button id="completeBtn" class="primary" onclick="markDone()">${state.done.includes(id)?'✓ 这课已读完':'我已读完这一课 ✓'}</button><div><button onclick="openLesson(${id-1})" ${id===1?'disabled':''}>← 上一课</button><button onclick="${id===12?'overview()':`openLesson(${id+1})`}">${id===12?'回到课程总览':'下一课 →'}</button></div></div><footer>读完标记与自测答案分开记录。看懂后再继续，不需要一次学完。</footer>`;if(state.answers[id]!==undefined)answer(state.answers[id],false);initLab(l.visual);focusMain()}
function answer(i,persist=true){const l=lessons[current-1];if(!l||!Number.isInteger(i)||i<0||i>=l.options.length)return;const good=i===l.answer;document.querySelectorAll('.quiz-options button').forEach((b,k)=>b.classList.toggle('chosen',k===i));document.getElementById('quizFeedback').innerHTML=`<strong>${good?'理解对了。':'再看一下这个关键点：'}</strong> ${esc(l.why)}${good?'':' 你可以重新选择。'}`;if(persist){state.answers[current]=i;save()}}
function markDone(){if(!state.done.includes(current)){state.done.push(current);save();toast('已记录，之后可以随时复习')}document.getElementById('completeBtn').textContent='✓ 这课已读完'}
const title=(name,sub)=>`<div class="lab-label">动手理解 / 学习演示</div><h3>${name}</h3><p>${sub}</p>`;
const path=(items)=>`<div class="diagram"><div class="diagram-row">${items.map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="diagram-node">${x}</div>`).join('')}</div></div>`;
function lab(kind){switch(kind){case 'workflow':return title('点一点这条简单流程','按顺序选择，看看每一步的职责。')+`<div class="lab-row">${['准备模型','写画面要求','生成','保存结果'].map((s,i)=>`<button onclick="flowStep(${i})">${i+1} ${s}</button>`).join('<span class="arrow">→</span>')}</div><div id="flowResult" class="lab-result" aria-live="polite">先选择“准备模型”。</div>`;
case 'anatomy':return title('拆开看一个节点','点击名字、输入、输出或参数，说明会出现在下方。示意图省略了部分端口。')+`<div class="anatomy"><button class="node-title" onclick="anatomy('title')">KSampler · 采样器</button><div class="slots"><button onclick="anatomy('in')">● model 输入</button><button onclick="anatomy('out')">LATENT 输出 ●</button></div><div class="widgets"><button onclick="anatomy('param')">steps：20</button><button onclick="anatomy('param')">seed：42</button></div></div><div class="lab-result" id="anatomyResult" aria-live="polite">这是一个简化示意节点。</div>`;
case 'wire':return title('给保存图片节点接一条线','先选一个输出，再点击右侧输入，检查类型是否匹配。')+`<div class="lab-row"><div><button onclick="chooseWire('MODEL')">MODEL 输出 ●</button><button onclick="chooseWire('IMAGE')">IMAGE 输出 ●</button><button onclick="chooseWire('INT')">INT 输出 ●</button></div><span class="arrow">→</span><button id="targetPort" onclick="connectWire()">● Save Image / images 输入</button></div><div class="lab-result" id="wireResult" aria-live="polite">尚未选择输出。目标需要 IMAGE。</div>`;
case 'pipeline':return title('一步一步走过生成过程','这是经典文生图的概念图；模型与文字条件也会送入采样器。')+`<div class="diagram"><div id="pipelinePath" class="diagram-row"></div></div><div class="lab-row"><button onclick="pipeline(-1)">← 上一步</button><button onclick="pipeline(1)">下一步 →</button></div><div class="lab-result" id="pipelineResult" aria-live="polite"></div>`;
case 'roles':return title('三种工具，各做什么？','选择角色，对照你自己的工作流。')+`<div class="lab-row"><button onclick="role('model')">生成主模型</button><button onclick="role('encoder')">文本编码器</button><button onclick="role('vae')">VAE</button></div><div class="lab-result" id="roleResult" aria-live="polite">在上方选一个角色。</div>`;
case 'prompt':return title('把要求写清楚','组合一个简单镜头描述。这里只拼接文字，实际效果需对应模型验证。')+`<div class="lab-row"><label>主体 <select id="pSubject" onchange="promptBuild()"><option>橘猫</option><option>一只蓝色茶杯</option><option>一棵小树</option></select></label><label>动作 <select id="pAction" onchange="promptBuild()"><option>保持静止</option><option>缓慢转动</option><option>轻轻摇晃</option></select></label><label>镜头 <select id="pCamera" onchange="promptBuild()"><option>固定近景</option><option>缓慢推近</option><option>固定全景</option></select></label></div><div class="lab-result" id="promptResult" aria-live="polite"></div><p>组合要符合对象的物理特点。例如茶杯“转动”与树枝“摇晃”应有合理原因，正式提示词需要继续细化。</p>`;
case 'seed':return title('同一种子，怎样帮助比较？','下面是数字种子控制的色块示意，不是 AI 成图或噪声算法复刻。改变数字后观察，再改回 42。')+`<div class="seed-row"><div><label>示例种子 <input type="number" id="seedInput" min="0" max="999999" value="42" oninput="seedShow()"></label><div class="lab-row"><button onclick="setSeed(42)">设为 42</button><button onclick="setSeed(73)">设为 73</button></div><p>同一规则和同一种子得到同一幅示意图。真实 AI 生成还受到其他条件和运行实现影响。</p></div><div id="seedMosaic" class="seed-mosaic" aria-label="随种子变化的确定性色块图"></div></div>`;
case 'bypass':return title('正常、旁路、停用有什么不同？','只演示一个 MODEL 输入、一个 MODEL 输出的 LoRA 节点。')+`<div class="lab-row"><button onclick="bypass('normal')">正常</button><button onclick="bypass('bypass')">旁路</button><button onclick="bypass('never')">停用</button></div><div class="run-path" id="bypassPath"></div><div class="lab-result" id="bypassResult" aria-live="polite"></div>`;
case 'video':return title('亲手算一次播放时长','输入帧数、fps 和宽高，结果会立即更新；这里只计算，不生成视频。')+`<div class="lab-row"><label>总帧数 <input id="vf" type="number" min="1" max="100000" value="124" oninput="videoCalc()"></label><label>fps <input id="vr" type="number" min="1" max="240" value="24" oninput="videoCalc()"></label><label>宽 <input id="vw" type="number" min="1" max="20000" value="864" oninput="videoCalc()"></label><label>高 <input id="vh" type="number" min="1" max="20000" value="480" oninput="videoCalc()"></label></div><div class="lab-row"><button onclick="videoPreset(124,24)">原快照：124 帧 / 24 fps</button><button onclick="videoPreset(124,48)">只改帧率：124 / 48</button><button onclick="videoPreset(248,48)">理想化双倍帧数：248 / 48</button></div><div class="meter" id="videoResult" aria-live="polite"></div><p>“双倍帧数”用于算术演示。实际补帧可能有首尾边界处理，应以输出帧数为准。</p>`;
case 'h3':return title('从结果向上游找证据','先看保存节点需要什么，再追溯导演台提供什么。')+path(['#145 导演台<small>输出 IMAGE / AUDIO / fps</small>','#23 图像分线<small>传递 IMAGE</small>','#30 视频封装<small>组合画面、声音、帧率</small>'])+`<p>声音另经 #84 送入 #30；上方简图只画图像路线。点击本课下方真实节点，查看完整的输入来源。</p>`;
case 'troubleshoot':return title('选择你看到的现象','这里给的是排查顺序，不会对你的设备做任何修改。')+`<div class="lab-row"><button onclick="trouble('node')">unknown node type</button><button onclick="trouble('model')">模型列表空</button><button onclick="trouble('shape')">shape / channels 不匹配</button><button onclick="trouble('oom')">Out of memory</button></div><div class="lab-result" id="troubleResult" aria-live="polite">先选择一种现象。</div>`;
case 'finish':return title('现在，你可以这样介绍它','试着把这句话用自己的话说出来，再对照真实节点。')+`<div class="lab-result">“这份工作流先加载配套模型，在导演台里根据首图和提示词生成画面与声音，再经过音轨选择和视频封装。当前部分后期模块处于旁路。”</div><p>这句话概括结构；没有运行验证时，不把它当作本次已成功生成的证明。</p>`;default:return ''}}
let wireSource=null,pipeIndex=0;
function initLab(kind){wireSource=null;pipeIndex=0;if(kind==='pipeline')pipeline(0);if(kind==='prompt')promptBuild();if(kind==='seed')seedShow();if(kind==='bypass')bypass('normal');if(kind==='video')videoCalc();if(kind==='finish')capstone()}
function flowStep(i){const texts=['先载入与任务匹配的模型。加载器输出的是模型对象，不是成片。','写明主体、动作和场景；文字需要编码后成为生成条件。','生成过程使用模型与条件，逐步处理内部表示。经典流程随后还要解码。','把可见图片或带帧率的画面序列保存为文件；视频还要正确组合音轨。'];document.getElementById('flowResult').textContent=texts[i]}
function anatomy(kind){document.getElementById('anatomyResult').textContent={title:'名字：这是采样器节点的类型/显示名，帮助识别它的职责。',in:'输入：model 需要一个 MODEL 对象，由模型加载器或模型补丁链提供。',out:'输出：这里交出 LATENT 潜变量。要得到普通图片，通常继续接 VAE Decode。',param:'参数：steps 决定更新步数，seed 参与确定随机噪声。示意数值不是 H3 的推荐配置。'}[kind]}
function chooseWire(type){wireSource=type;document.getElementById('wireResult').textContent=`已选择 ${type} 输出。现在点击 Save Image 的输入。`;document.getElementById('wireResult').classList.remove('good')}
function connectWire(){const el=document.getElementById('wireResult');if(!wireSource){el.textContent='先选择一个输出，再连接输入。';return}const good=wireSource==='IMAGE';el.textContent=good?'IMAGE → IMAGE，类型匹配。这条连接可以把图片交给保存节点。':`${wireSource} → IMAGE，类型不匹配。请换成 IMAGE 输出。`;el.classList.toggle('good',good)}
function pipeline(delta){pipeIndex=Math.max(0,Math.min(3,pipeIndex+delta));const steps=[['准备潜变量','LATENT'],['采样更新','LATENT'],['VAE 解码','IMAGE'],['保存图片','文件']];document.getElementById('pipelinePath').innerHTML=steps.map((s,i)=>`${i?'<span class="arrow">→</span>':''}<div class="diagram-node ${i===pipeIndex?'current':''}">${s[0]}<small>${s[1]}</small></div>`).join('');document.getElementById('pipelineResult').textContent=['先设定潜空间的尺寸与批量。采样过程会结合种子准备噪声；此时还没有可见图片。','采样器接收模型、文字条件和潜变量，执行更新。得到的仍然是 LATENT。','VAE Decode 将 LATENT 转换为像素 IMAGE，才成为普通图片数据。','保存节点接收 IMAGE，写入图片文件。保存路径与环境由平台决定。'][pipeIndex]}
function role(kind){document.getElementById('roleResult').textContent={model:'生成主模型：对应 #38 FL2VA。经过补丁链后，最终从 #90 接入导演台 model。',encoder:'文本编码器：对应 #39 Qwen3-VL。输出 CLIP 类型接口并接入导演台 clip。',vae:'VAE：#3 负责视频，#4 负责音频。二者分别进入导演台，不能仅凭同为 VAE 类型就互换。'}[kind]}
function promptBuild(){document.getElementById('promptResult').textContent=`${document.getElementById('pSubject').value}在柔和侧光下${document.getElementById('pAction').value}，${document.getElementById('pCamera').value}。`}
function setSeed(n){document.getElementById('seedInput').value=n;seedShow()}
function seedShow(){const raw=Number(document.getElementById('seedInput').value);if(!Number.isFinite(raw))return;let x=((Math.floor(raw)>>>0)+0x9e3779b9)>>>0,html='';for(let i=0;i<96;i++){x^=x<<13;x^=x>>>17;x^=x<<5;const r=(x>>>0)/4294967296;html+=`<i style="background:hsl(${Math.floor(70+r*70)} 25% ${Math.floor(20+r*55)}%)"></i>`}document.getElementById('seedMosaic').innerHTML=html}
function bypass(mode){const el=document.getElementById('bypassPath'),out=document.getElementById('bypassResult');if(mode==='normal'){el.innerHTML='MODEL → [LoRA 应用补丁] → 修改后的 MODEL';out.textContent='正常：当这条链被执行时，LoRA 对主模型应用补丁。'}if(mode==='bypass'){el.innerHTML='MODEL → <span class="skip">[LoRA 自身处理]</span> → 原 MODEL';out.textContent='旁路：跳过这个 LoRA 的处理，尝试传递兼容的 MODEL 数据。'}if(mode==='never'){el.innerHTML='MODEL → <span class="stop">[LoRA 停用] × 下游缺少数据</span>';out.textContent='停用：这条单路示意中，下游可能拿不到必需 MODEL，导致无法继续。'}}
function videoPreset(f,r){document.getElementById('vf').value=f;document.getElementById('vr').value=r;videoCalc()}
function videoCalc(){const values=['vf','vr','vw','vh'].map(id=>Number(document.getElementById(id).value)),[f,r,w,h]=values;const el=document.getElementById('videoResult');if(values.some(v=>!Number.isFinite(v)||v<=0)){el.textContent='请输入大于 0 的数值。';return}if(![f,w,h].every(Number.isInteger)){el.textContent='帧数、宽和高需要为整数。';return}el.innerHTML=`<div><b>${(f/r).toFixed(2)} 秒</b><span>${f} 帧 ÷ ${r} fps</span></div><div><b>${w} × ${h}</b><span>画面宽高 / 像素</span></div><div><b>${(w*h/1e6).toFixed(2)} MP</b><span>每帧像素总量，不是画质评分</span></div>`}
function trouble(kind){document.getElementById('troubleResult').textContent={node:'先找报错节点的类型名及插件来源 → 核对该插件是否安装并加载成功 → 再查版本。缺失节点代码与缺模型文件是两种问题。',model:'先核对加载器类别 → 核对该模型是否存在于当前平台可用模型中 → 按平台提供的方式刷新/选择。不要只根据文件名相似就替换。',shape:'先核对主模型、VAE、编码器、LoRA 是否配套 → 再检查输入类型与尺寸限制 → 从已知可用副本恢复基准。',oom:'先记录当前宽高、总帧数和批量 → 在练习副本中降低这些设置 → 再按模板要求核对显存和资源。不要把 OOM 当作提示词错误。'}[kind]}
const capItems=[['找到基础输出，指出它需要画面、声音和帧率。',30],['找到导演台，确认当前模式是 i2v。',145],['说明参考图位于内部素材槽，#78 没有接入生成。',78],['用 124÷24 解释为什么约为 5.17 秒。',145],['指出一个旁路模块，解释它与正常模式有什么区别。',19]];
function capstone(){document.getElementById('capstone').innerHTML=capItems.map(([text,n],i)=>`<label class="capitem"><input type="checkbox" ${state.cap.includes(i)?'checked':''} onchange="capToggle(${i},this.checked)"><span>${text}<a href="index.html?node=${n}">查看 #${n} ${nodeNames[n]} ↗</a></span></label>`).join('')}
function capToggle(i,checked){state.cap=state.cap.filter(x=>x!==i);if(checked)state.cap.push(i);save()}
const terms=[['工作流 Workflow','由节点、连接和参数组织起来的一套处理步骤。',1],['节点 Node','完成一项具体任务的模块，如加载、变换、生成或保存。',2],['端口 Port','节点接收输入或交出输出的位置。',3],['连线 Link','把一个节点的输出送到另一个节点的输入。',3],['参数 / 控件 Widget','决定节点如何工作的填写项或选择项。部分可以转为接线输入。',2],['主模型 MODEL','生成过程中使用的模型对象，加载器与补丁链会继续传递它。',5],['Checkpoint','模型检查点文件；有些包含主模型、编码器和 VAE，不能假设每份都一样。',5],['编码器 / CLIP','把文字等条件转成模型能用的表示；接口名称不一定等于具体编码器架构。',5],['VAE','连接像素/音频与相应潜空间表示的编码解码组件。',5],['潜变量 LATENT','模型内部使用的表示，通常需要解码后才能得到可见图片。',4],['IMAGE','像素图片或图像帧批次。',3],['CONDITIONING','经过编码、供生成过程使用的条件数据。',6],['采样器 Sampler','根据模型和条件，对潜变量执行一系列更新的过程/节点。',4],['Seed 种子','参与确定随机噪声的数值；复现还要固定其他条件。',7],['Steps 步数','采样更新的次数，更多计算不保证始终更好。',7],['CFG 引导强度','控制条件引导的参数，数值含义要结合具体模型。',7],['Scheduler 调度器','决定采样中噪声时间步或强度分配的策略。',7],['Denoise 降噪强度','在相应采样流程中影响改动程度，不能作为所有参考节点的通用相似度。',8],['LoRA','应用到兼容模型上的权重补丁，可承担风格、概念或加速等用途。',8],['正常 / Always','节点在所需链路中可按执行机制工作；不表示刚刚已运行。',8],['旁路 / Bypass','跳过节点自身处理，尝试传递兼容上游数据。',8],['停用 / Never','不执行节点，可能导致下游缺少输入。',8],['帧率 FPS','视频每秒播放多少帧。',9],['补帧','估计并插入中间帧，与增加宽高不同。',9],['超分 / 放大','提高画面尺寸；普通插值和模型超分的做法、效果不同。',9],['OOM / 显存不足','计算资源无法承受当前工作负载时的一类错误。',11],['t2v / i2v / fl2v','文字、单图或首尾帧条件的视频生成模式，模型家族需要匹配。',10],['导出 / 封装','把图像序列、播放帧率与可选音轨组织成视频文件。',9],['自定义节点 / 插件','扩展 ComfyUI 功能的节点代码包，与模型权重文件分别管理。',11],['INT / FLOAT / STRING','整数、小数、文本三类基础数据类型。',3]];
function openGlossary(){current=-1;route('#glossary');updateProgress();main.innerHTML='<header class="course-head"><div class="eyebrow">随时查，不用背</div><h1>术语速查</h1><p class="muted">先读中文意思，再回到对应课程看例子。</p></header><input id="termSearch" class="glossary-search" type="search" placeholder="搜索：如 VAE、补帧、种子" aria-label="搜索术语" oninput="renderTerms(this.value)"><div class="glossary-grid" id="termGrid"></div>';renderTerms('');focusMain()}
function renderTerms(query){const q=query.toLowerCase().trim(),arr=terms.filter(t=>(t[0]+' '+t[1]).toLowerCase().includes(q));document.getElementById('termGrid').innerHTML=arr.length?arr.map(t=>`<article class="term"><h3>${esc(t[0])}</h3><p>${esc(t[1])}</p><button onclick="openLesson(${t[2]})">去第 ${t[2]} 课看例子 →</button></article>`).join(''):'<p class="muted">暂未找到，可以换成中文或英文关键词。</p>'}
document.getElementById('overviewBtn').onclick=overview;document.getElementById('glossaryBtn').onclick=openGlossary;
function fromHash(){const m=location.hash.match(/^#lesson-(\d+)$/);if(m&&Number(m[1])>=1&&Number(m[1])<=12)openLesson(Number(m[1]));else if(location.hash==='#glossary')openGlossary();else overview()}
window.addEventListener('hashchange',fromHash);fromHash();
